insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('84c8489a-6188-85de-9d31-ce688944c25d', 'ru', 'Открыть кафе без лицензии — общепит в свободном режиме допуска', null) on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('84c8489a-6188-85de-9d31-ce688944c25d', 'ru', 'Деятельность кафе и ресторанов не входит ни в один из перечней ЗРУ-701: ни в лицензируемые виды (приложение №1), ни в разрешительные (№2), ни в уведомительные (№3). Специальный допуск на само кафе не нужен — действуют общие правила: регистрация бизнеса, санитарные нормы, кассовая дисциплина. Отдельные уведомления появляются только у сопутствующих видов деятельности — алкоголь, пиво, табак (см. соседние карточки).', '[{"step":"Убедиться, что в вашем формате нет видов деятельности с отдельным допуском (алкоголь, пиво, табак)"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
