insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('69d03696-5488-1ee3-f4ab-d6d6385a5ee7', 'ru', 'Подать уведомление в налоговый орган до начала продажи алкоголя', 'Продажа алкоголя без уведомления = работа без допуска: 5–25 БРВ (ст. 165 КоАО)') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('69d03696-5488-1ee3-f4ab-d6d6385a5ee7', 'ru', 'Реализация алкогольной продукции предприятиями общественного питания — уведомительный вид деятельности (приложение №3 к ЗРУ-701). С 21.02.2025 уведомление о начале деятельности направляется налоговым органам (закон ЗРУ-1034); подача — онлайн через license.gov.uz. Продавать алкоголь могут только юридические лица — для ИП этот вид деятельности недоступен.', '[{"step":"Зарегистрировать юридическое лицо (ИП продавать алкоголь не может)"},{"step":"Направить уведомление через license.gov.uz до первой продажи"},{"step":"Начать уплачивать ежемесячный сбор за право реализации (отдельная карточка)"}]'::jsonb, '[{"name":"Уведомление о начале деятельности","where_to_get":"license.gov.uz"}]'::jsonb, '[{"amount":"5–25 БРВ","article":"ст. 165 КоАО","extra":"деятельность без обязательного уведомления"}]'::jsonb) on conflict do nothing;
