insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('1c830523-f468-7d68-f43d-e096cad74149', 'ru', 'Платить ежемесячный сбор за право реализации алкоголя', 'Недоимка по сбору взыскивается по Налоговому кодексу') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('1c830523-f468-7d68-f43d-e096cad74149', 'ru', 'За право продавать алкоголь общепит платит ежемесячный сбор (ст. 455 НК) — вдвое ниже ставок розничных магазинов. Ставки утверждаются ежегодно; на 2024 год: Ташкент — 600 тыс., Нукус и облцентры — 420 тыс., прочие города — 300 тыс., сёла — 150 тыс. сум в месяц. Уплата — предоплатой до 10 числа текущего месяца; сбор начисляется с месяца подачи уведомления.', '[{"step":"Уточнить действующую ставку для вашей местности на soliq.uz"},{"step":"Платить сбор предоплатой до 10 числа каждого месяца","deadline":"ежемесячно"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
