insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('b6e6c6d1-a271-0f32-baaa-29921afcf253', 'ru', 'Уведомить о торговле пивом и табаком и платить сбор 10% БРВ', 'Торговля без уведомления = работа без допуска (ст. 165 КоАО)') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('b6e6c6d1-a271-0f32-baaa-29921afcf253', 'ru', 'Розничная торговля пивной и табачной продукцией с 01.09.2024 ведётся в уведомительном порядке с ежемесячным сбором 10% БРВ (ПП-203 от 30.05.2024). Уведомительный порядок торговли алкоголем и табаком закреплён и законом ЗРУ-1098 от 27.11.2025. Если кафе продаёт только пиво (без крепкого алкоголя), действует именно этот режим.', '[{"step":"Направить уведомление о торговле пивом/табаком","cost":"сбор 10% БРВ в месяц"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
