insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('2d00aef4-f989-914d-e884-b9cc03db6c0d', 'ru', 'Действующие санитарные правила для кафе и ресторанов — СанҚваН №0027-22 (в силе с 20.08.2022): раздельные производственные, складские и клиентские зоны; стены из материалов, выдерживающих влажную уборку и дезинфекцию; водонепроницаемые нескользкие полы; механическая или естественная вентиляция для поддержания микроклимата.', '[{"step":"Спланировать раздельные зоны: кухня, склады, зал для гостей, бытовые помещения"},{"step":"Отделать стены и полы моющимися дезинфицируемыми материалами"},{"step":"Обеспечить вентиляцию, поддерживающую нормируемый микроклимат"}]'::jsonb, '[]'::jsonb, '[{"amount":"5–10 БРВ (должностные лица 15–20)","article":"ст. 53 КоАО","extra":"в редакции ЗРУ-878, действует с 17.02.2024"}]'::jsonb) on conflict do nothing;
