insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('bc3b0bd2-be26-2317-d718-744d5bfaa466', 'ru', 'Не размещать точку с алкоголем и табаком ближе 100 м от школ и мечетей', 'Продажа в запрещённой зоне — нарушение ЗРУ-844') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('bc3b0bd2-be26-2317-d718-744d5bfaa466', 'ru', 'Если кафе продаёт алкоголь или табак, объект не может располагаться ближе 100 метров по прямой линии от образовательных, спортивных и религиозных организаций (ЗРУ-844; исключение — торговые комплексы площадью свыше 1000 м²). Запрещены также продажа без участия продавца (автоматы, полки самообслуживания), через электронную коммерцию и доставку — кроме игристых и натуральных вин.', '[{"step":"Перед арендой проверить дистанцию до школ, спортобъектов и религиозных организаций"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
