insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('ab338c13-a4e5-80b8-a0c4-767e229d2289', 'ru', 'Вести производственный контроль по принципу HACCP', 'Нарушение санитарного законодательства: 5–10 БРВ, должностные лица 15–20 БРВ (ст. 53 КоАО)') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('ab338c13-a4e5-80b8-a0c4-767e229d2289', 'ru', 'С 17.06.2025 общие санитарные правила безопасности пищевой продукции (СанҚваН №0079-24) закрепляют для всех звеньев пищевой цепи принцип «анализ опасностей и критические контрольные точки» (HACCP): предотвращение биологического, химического и физического загрязнения, входной контроль сырья, записи о температурных режимах и дезинфекции.', '[{"step":"Определить критические контрольные точки кухни: приёмка, хранение, тепловая обработка"},{"step":"Проверять сырьё при приёмке на соответствие санитарным нормам","deadline":"постоянно"},{"step":"Вести журналы температурных режимов и дезинфекции","deadline":"постоянно"}]'::jsonb, '[]'::jsonb, '[{"amount":"5–10 БРВ (должностные лица 15–20)","article":"ст. 53 КоАО"}]'::jsonb) on conflict do nothing;
