insert into public.requirement_contents (requirement_id, lang, title, sanction_summary) values ('82abe10b-ec07-7f56-0590-eea2b1a5a5b9', 'ru', 'Не допускать в меню небезопасную и просроченную продукцию', 'Сбыт небезопасной продукции: штраф до 200 БРВ, при гибели людей — до 12 лет лишения свободы (УК, ред. ЗРУ-878)') on conflict do nothing;
insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('82abe10b-ec07-7f56-0590-eea2b1a5a5b9', 'ru', 'Закон №483-I «О качестве и безопасности пищевой продукции» обязывает соблюдать сроки годности и изымать небезопасную продукцию из оборота. Уголовная ответственность за сбыт товаров и услуг, не отвечающих требованиям безопасности, усилена с 17.02.2024: штраф 100–200 БРВ, при отягчающих — ограничение или лишение свободы до 3–5 лет, при гибели людей — 7–12 лет.', '[{"step":"Контролировать сроки годности сырья и заготовок","deadline":"постоянно"},{"step":"Немедленно изымать из оборота продукцию с признаками небезопасности"}]'::jsonb, '[]'::jsonb, '[{"amount":"100–200 БРВ","article":"УК (ред. ЗРУ-878)","extra":"сбыт продукции, не отвечающей требованиям безопасности; номер статьи — на юрпроверке"},{"amount":"7–12 лет лишения свободы","article":"УК (ред. ЗРУ-878)","extra":"при гибели людей или иных тяжких последствиях"}]'::jsonb) on conflict do nothing;
insert into public.requirement_applicability (id, requirement_id, scope, code) values ('f8b609fc-de0d-1808-5a56-fd6df94cb1a4', '82abe10b-ec07-7f56-0590-eea2b1a5a5b9', 'oked_code', '56.10') on conflict (id) do nothing;
