insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('9ab9f216-19d3-ab5c-7e41-0c62764e48ce', 'ru', 'Правила общепита (ПКМ №75 от 13.02.2003, действующая редакция) требуют: меню на государственном языке (плюс винная/чайная/кофейная карта по специализации заведения), прейскуранты и ценники в буфетах и кафетериях, вывеску с информацией о предприятии, книгу жалоб и предложений и уголок потребителя. Информацию можно дублировать на других языках.', '[{"step":"Подготовить меню на узбекском языке (дубли на других языках — по желанию)"},{"step":"Разместить уголок потребителя и завести книгу жалоб и предложений"}]'::jsonb, '[]'::jsonb, '[{"amount":"в крупном размере: граждане 70, должностные лица 80 БРВ","article":"ст. 164 КоАО","extra":"штрафы удвоены ЗРУ-878"}]'::jsonb) on conflict do nothing;
