insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('f3fffdc5-6270-7a59-1cd3-e0664f3dc0b6', 'ru', 'Автоматическое включение в счёт 10–20% «за обслуживание» без реальной альтернативы и предварительного уведомления гостя — нарушение прав потребителей (официальная позиция Комитета по развитию конкуренции и защите прав потребителей, ноябрь 2025). Нарушениями названы также навязывание депозита до заказа, скрытые доплаты и плата за неоказанный сервис.', '[{"step":"Предупреждать о сервисном сборе до заказа и давать альтернативу без доплаты"},{"step":"Убрать из счетов автоматические доплаты за неоказанные услуги"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
