insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('d06c84e7-349b-5dec-fb32-562d30ccbea5', 'ru', 'Работники общепита проходят предварительный (при приёме на работу) и периодические медицинские осмотры по положению приказа Минздрава №200 (рег. МЮ №2387); обязанность организовать медосмотры закреплена Трудовым кодексом, расходы несёт работодатель.', '[{"step":"Организовать предварительный медосмотр до допуска сотрудника к работе"},{"step":"Вести график периодических осмотров персонала","deadline":"по графику"}]'::jsonb, '[]'::jsonb, '[{"amount":"уточняется","article":null,"extra":"номер статьи КоАО — на юрпроверке"}]'::jsonb) on conflict do nothing;
