insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('2c57e15a-2b87-a24d-1005-b6ff42198113', 'ru', 'Вода и прохладительные напитки (с 01.03.2025), алкоголь, пиво и табак — маркированные группы: при продаже касса считывает Data Matrix-код, выбытие уходит через ОФД в систему Asl Belgisi, чек формируется только после ввода кода маркировки. Санкции ПП-190 от 23.05.2025: после двух предупреждений — 0,2%, 0,4%, 1%, 2% чистой выручки квартала за повторные нарушения.', '[{"step":"Зарегистрироваться в Asl Belgisi и подключить 2D-сканер к кассе"},{"step":"Сканировать код каждой маркированной единицы при продаже","deadline":"постоянно"}]'::jsonb, '[]'::jsonb, '[{"amount":"0,2% → 0,4% → 1% → 2% от чистой выручки квартала","article":"ПП-190 от 23.05.2025","extra":"после двух предупреждений, за повторные нарушения"}]'::jsonb) on conflict do nothing;
