insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('a4b9c4a5-225a-7f37-2b77-64196d9af880', 'ru', 'С июня 2025 действуют правила курьерской деятельности в электронной торговле (зарегистрированы Минюстом): курьер работает по трудовому или гражданско-правовому договору; при приёме оплаты обязательна онлайн-касса или выдача чека; еда перевозится в чистых дезинфицируемых термоконтейнерах; оператор обеспечивает курьеров термоконтейнерами, фискальными устройствами и спецодеждой со светоотражающими элементами. Точный реквизит акта уточняется юрвычиткой.', '[{"step":"Оформить курьеров по трудовому или ГПХ-договору"},{"step":"Выдать термоконтейнеры, фискальное устройство и спецодежду"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
