insert into public.requirement_details (requirement_id, lang, description, how_to_comply, documents, sanctions) values ('2bb63fe6-fcc3-5522-20d7-b2040e76fc7c', 'ru', 'С 01.01.2026 в Узбекистане внедряется, а с 01.07.2026 становится обязательным приём платежей через единый QR-код (UzQR) для всех объектов торговли и услуг (указ Президента от 10.12.2025). Единый QR дополняет, а не заменяет платёжный терминал.', '[{"step":"Получить UzQR у обслуживающего банка и разместить на кассе","deadline":"к 01.07.2026"}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict do nothing;
