-- Актуализация «Выбрать налоговый режим» (порог 5 млрд сум с 01.06.2026)
update public.requirement_details set description = 'Малый бизнес платит налог с оборота (стандартная ставка 4%); с 01.06.2026 порог обязательного перехода на общий режим (НДС 12% и налог на прибыль) повышен с 1 до 5 млрд сум годового дохода. Общепиту, торговле и услугам доступен добровольный упрощённый НДС 6% с освобождением от налога на прибыль. Режим стоит определить до старта: смена задним числом означает доначисления.', how_to_comply = '[{"step":"Оценить плановую выручку: до 5 млрд сум в год — можно остаться на налоге с оборота"},{"step":"Отслеживать порог 5 млрд сум и вовремя перейти на общий режим","deadline":"постоянно"}]'::jsonb where requirement_id = 'f43409c3-2147-7ca2-8f4e-83b30d88df1f' and lang = 'ru';
